#!/usr/bin/env python3
"""Create a deterministic, hash-complete RPSME Bundle from a validated package."""

from __future__ import annotations

import argparse
import hashlib
import json
import mimetypes
import re
import zipfile
from pathlib import Path, PurePosixPath
from typing import Any

from literature_checks import check_literature
from rpsme_ontology_v2.adapter_v13 import canonical_json_bytes
from rpsme_ontology_v2.bundle import validate_bundle
from rpsme_ontology_v2.validator import validate_package


FIXED_TIME = (1980, 1, 1, 0, 0, 0)


def digest(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def safe_path(value: str) -> bool:
    path = PurePosixPath(value)
    return bool(value) and not path.is_absolute() and all(part not in {"", ".", ".."} for part in path.parts) and "\\" not in value


def zip_write(bundle: zipfile.ZipFile, path: str, payload: bytes) -> None:
    info = zipfile.ZipInfo(path, FIXED_TIME)
    info.compress_type = zipfile.ZIP_DEFLATED
    info.external_attr = 0o100644 << 16
    bundle.writestr(info, payload)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("package", type=Path)
    parser.add_argument("--sources", type=Path, required=True, help="Local path map generated by build_asset_manifest.py")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--companion-output",
        type=Path,
        help="Write the exact ontology JSON embedded in the bundle for paired Materials Ontology OS upload.",
    )
    parser.add_argument("--validation-report", type=Path)
    args = parser.parse_args()
    root = Path(__file__).resolve().parent.parent
    package = json.loads(args.package.read_text(encoding="utf-8"))
    if package.get("schema_version") not in {"rpsme-ontology-1.3", "rpsme-ontology-1.4"} or package.get("bundle", {}).get("delivery_mode") != "bundle":
        parser.error("package must be Ontology 1.3/1.4 with bundle.delivery_mode=bundle")

    contract = validate_package(package, root / "references/rpsme-patent-package-v2.schema.json")
    literature_issues = check_literature(package)
    validation = contract.to_dict()
    validation["literature_issues"] = literature_issues
    validation["valid"] = validation["valid"] and not any(row.get("severity") == "error" for row in literature_issues)
    if not validation["valid"]:
        if args.validation_report:
            args.validation_report.write_text(json.dumps(validation, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(json.dumps(validation, ensure_ascii=False, indent=2))
        return 1

    mapping_value = json.loads(args.sources.read_text(encoding="utf-8"))
    mappings = mapping_value.get("files", mapping_value) if isinstance(mapping_value, dict) else {}
    refs = {
        str(row.get("asset_id")): row.get("asset_role")
        for row in package.get("entities", {}).get("asset_references", []) if isinstance(row, dict)
    }
    payloads: dict[str, bytes] = {}
    file_rows: list[dict[str, Any]] = []
    raw_source_key = str(package.get("source", {}).get("publication_number") or package.get("source", {}).get("id") or "SOURCE")
    source_key = re.sub(r"[^A-Za-z0-9._:-]+", "-", raw_source_key).strip("-") or "SOURCE"
    ontology_path = f"ontology/{source_key}.rpsme.v2.json"
    ontology_payload = canonical_json_bytes(package)
    if args.companion_output:
        if args.companion_output.resolve() in {args.package.resolve(), args.output.resolve()}:
            parser.error("--companion-output must not overwrite the input package or ZIP output")
        args.companion_output.parent.mkdir(parents=True, exist_ok=True)
        args.companion_output.write_bytes(ontology_payload)
    payloads[ontology_path] = ontology_payload
    file_rows.append({
        "relative_path": ontology_path,
        "sha256": digest(ontology_payload),
        "byte_size": len(ontology_payload),
        "media_type": "application/json",
        "role": "ontology",
        "asset_id": None,
        "profile": {},
    })

    for asset in package.get("asset_manifest", {}).get("assets", []):
        if not isinstance(asset, dict) or asset.get("availability_status") != "bundled":
            continue
        relative = str(asset.get("relative_path") or "")
        if not safe_path(relative) or relative not in mappings:
            parser.error(f"missing or unsafe local source mapping for bundled asset: {relative!r}")
        source = Path(str(mappings[relative])).expanduser().resolve()
        payload = source.read_bytes()
        if digest(payload) != asset.get("sha256") or len(payload) != asset.get("byte_size"):
            parser.error(f"source file hash/size differs from asset descriptor: {relative}")
        payloads[relative] = payload
        role = refs.get(str(asset.get("asset_id")))
        if asset.get("origin_type") == "derived_thumbnail":
            role = "thumbnail"
        if role not in {"published_figure", "published_panel", "thumbnail", "native_raw", "structure_input", "input_script", "force_field", "mesh", "trajectory", "log", "output_table", "output_figure", "other"}:
            role = "other"
        file_rows.append({
            "relative_path": relative,
            "sha256": asset["sha256"],
            "byte_size": asset["byte_size"],
            "media_type": asset.get("media_type") or mimetypes.guess_type(relative)[0] or "application/octet-stream",
            "role": role,
            "asset_id": asset["asset_id"],
            "origin_type": asset["origin_type"],
            "parent_asset_id": asset.get("parent_asset_id"),
            "source_document_id": asset.get("source_document_id"),
            "source_locator": asset.get("source_locator") or {},
            "derivation": asset.get("derivation") or {},
            "rights": asset["rights"],
            "profile": asset.get("profile") or {},
        })

    validation_payload = canonical_json_bytes(validation)
    validation_path = "validation/validation.json"
    payloads[validation_path] = validation_payload
    file_rows.append({
        "relative_path": validation_path,
        "sha256": digest(validation_payload),
        "byte_size": len(validation_payload),
        "media_type": "application/json",
        "role": "validation",
        "asset_id": None,
        "profile": {},
    })
    generator = package.get("generator", {})
    manifest = {
        "bundle_version": "rpsme-bundle-1.0",
        "source_key": source_key,
        "ontology_path": ontology_path,
        "ontology_sha256": digest(ontology_payload),
        "created_at": package.get("generated_at"),
        "generator": {"name": str(generator.get("name") or "materials-literature-rpsme-json"), "version": str(generator.get("version") or "1.2.2")},
        "files": sorted(file_rows, key=lambda row: row["relative_path"]),
        "profile": {"deterministic_zip": True, "input_execution": "forbidden"},
    }
    manifest_payload = canonical_json_bytes(manifest)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(args.output, "w") as bundle:
        zip_write(bundle, "manifest.json", manifest_payload)
        for path in sorted(payloads):
            zip_write(bundle, path, payloads[path])

    bundle_report = validate_bundle(
        args.output,
        manifest_schema_path=root / "references/rpsme-bundle-manifest-v1.schema.json",
        package_schema_path=root / "references/rpsme-patent-package-v2.schema.json",
    ).to_dict()
    validation["bundle"] = bundle_report
    validation["valid"] = validation["valid"] and bundle_report["valid"]
    validation["bundle_sha256"] = digest(args.output.read_bytes())
    validation["bundle_path"] = str(args.output)
    if args.companion_output:
        validation["companion_json_path"] = str(args.companion_output)
        validation["companion_json_sha256"] = digest(args.companion_output.read_bytes())
        validation["companion_matches_embedded_ontology"] = validation["companion_json_sha256"] == manifest["ontology_sha256"]
    if args.validation_report:
        args.validation_report.write_text(json.dumps(validation, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(validation, ensure_ascii=False, indent=2))
    return 0 if validation["valid"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
